from h import *
M = []
# ------------------------------------------------------------------ 1.5
M.append(dict(id="1.5", go=1, slug="self-organisation", title="Self-organisation: lanes, oscillations and waves", minutes=30, tag="Patterns", systems=["flow", "people"],
 summary="Without a leader, crowds form lanes in counterflow, take turns at narrow doors, and make stop-and-go waves at high density. Simple local rules create these patterns.",
 outcomes=["describe lane formation, door oscillations and stop-and-go waves", "explain how simple local rules can create large patterns", "recognise when a pattern helps the flow and when it warns of danger"],
 narration_en="Watch a busy station corridor where people walk in both directions. Nobody gives orders, yet within seconds the crowd sorts itself into lanes: people heading the same way follow each other, because walking behind someone going your way means fewer collisions. At a narrow door with people going both ways, small groups pass in turns, like traffic lights nobody installed. In very dense crowds, movement becomes stop-and-go: waves of stopping travel backwards through the crowd, like the ripples in a traffic jam on a motorway. These patterns are called self-organisation. They come from simple, local rules: avoid the person in front, follow someone going your way, step into a gap. Some patterns help, like lanes, which raise flow. Others are warnings: stop-and-go waves mean the crowd is near or above capacity. In this module you will see these patterns emerge in a small simulation, and learn to read them as signals.",
 narration_ar="راقب ممراً مزدحماً في محطة يسير فيه الناس في الاتجاهين. لا أحد يصدر الأوامر، ومع ذلك يرتّب الحشد نفسه خلال ثوانٍ في مسارات: من يتجهون في الاتجاه نفسه يتبع بعضهم بعضاً، لأن السير خلف شخص يسير في اتجاهك يعني تصادمات أقل. وعند باب ضيق يعبره الناس في الاتجاهين، تمرّ مجموعات صغيرة بالتناوب، كأنها إشارات مرور لم يركّبها أحد. وفي الحشود الكثيفة جداً تصبح الحركة توقفاً وانطلاقاً: موجات من التوقف تنتقل إلى الخلف عبر الحشد، كالتموجات في ازدحام السيارات على الطريق السريع. تُسمّى هذه الأنماط التنظيم الذاتي. وهي تنشأ من قواعد بسيطة ومحلية: تجنّب الشخص الذي أمامك، واتبع من يسير في اتجاهك، وادخل في الفراغ. بعض الأنماط مفيد، كالمسارات التي ترفع التدفق. وبعضها إنذار: فموجات التوقف والانطلاق تعني أن الحشد قريب من سعته أو تجاوزها. سترى في هذه الوحدة هذه الأنماط تنشأ في محاكاة صغيرة، وتتعلم قراءتها كإشارات.",
 diagram=dict(title="Local rules, global patterns", caption="Each person follows simple rules about neighbours. Together they create lanes, turn-taking and waves that nobody planned.",
   nodes=[N("rule", "Local rules", "avoid, follow, fill gaps", 130, 120, "people", "Each person reacts only to those close by: keep distance, step aside from oncoming people, follow someone heading your way."),
          N("lane", "Lane formation", "counterflow sorts itself", 450, 100, "flow", "In two-way corridors people end up in lanes of uniform direction. Lanes reduce conflicts and raise flow."),
          N("osc", "Oscillations", "turn-taking at doors", 450, 250, "flow", "At a narrow door used both ways, small groups pass in alternating bursts, as pressure builds on one side then the other."),
          N("sag", "Stop-and-go waves", "high density warning", 450, 410, "risk", "Near capacity, small slowdowns grow into waves moving backwards through the crowd (Helbing et al. 2007 observed them at the Jamarat Bridge)."),
          N("good", "Helpful", "more flow, fewer conflicts", 770, 160, "manage", "Lanes and zipper effects make better use of space. Designers can encourage them, for example with a central divider."),
          N("bad", "Warning signs", "near capacity", 770, 360, "risk", "Stop-and-go waves and crowd turbulence warn that density is too high: time to reduce inflow.")],
   edges=[E("rule", "lane"), E("rule", "osc"), E("rule", "sag"), E("lane", "good", "raises flow"), E("osc", "good"), E("sag", "bad", "danger")],
   tour=[T(["rule"], "Every pattern starts with simple local rules: keep distance, step aside, follow someone going your way."),
         T(["lane"], "In two-way flow, these rules sort the crowd into lanes.", [["rule", "lane"]]),
         T(["osc"], "At narrow doors, the two directions take turns.", [["rule", "osc"]]),
         T(["sag"], "At high density, slowdowns grow into stop-and-go waves.", [["rule", "sag"]]),
         T(["good", "bad"], "Some patterns help the flow; others warn that density is too high.", [["lane", "good"], ["sag", "bad"]])]),
 sections=[
  S("Lanes in counterflow", "<p>In a two-way corridor, people who follow someone walking their way meet fewer oncoming walkers. This small advantage spreads: soon the corridor carries <b>lanes of uniform direction</b>. Lane formation is one of the most robust findings in crowd dynamics and appears in experiments and in models such as the social force model (Helbing and Molnár 1995).</p>",
    ("Lanes", "flow", "Two-way flows sort into lanes.", [("Follow your direction", "Fewer collisions."), ("Nobody plans it", "Self-organised."), ("Seen in models", "Social force reproduces it.")])),
  S("Taking turns at doors", "<p>At a narrow door with people going both ways, one side wins for a while, then pressure on the other side grows and the direction flips. The result is <b>oscillation</b>: alternating bursts. One-way doors, or separate in and out doors, remove the conflict.</p>",
    ("Oscillations", "flow", "Alternating bursts at narrow two-way doors.", [("Pressure builds", "Then the direction flips."), ("Fix", "Separate in and out doors."), ("Same at crossings", "Groups cross in turns.")])),
  S("Stop-and-go waves", "<p>When density is near capacity, one person slowing down makes the person behind slow down a little more, and so on. The disturbance grows and travels <b>backwards</b> through the crowd as a stop-and-go wave. Helbing, Johansson and Al-Abideen (2007) filmed such waves at the Jamarat Bridge before the 2006 disaster, followed by crowd turbulence (module 1.7).</p>",
    ("Stop-and-go", "risk", "Waves of stopping travel backwards.", [("Near capacity", "Small slowdowns grow."), ("Moves backwards", "Against the walking direction."), ("Jamarat 2006", "Filmed before the disaster.")])),
  S("Reading patterns as signals", "<p>Patterns are information. <b>Lanes</b> mean the crowd is coping. <b>Stop-and-go</b> means it is near capacity. <b>Irregular, random-looking surges</b> mean it is far beyond safe density. Control-room staff learn to watch for these changes on cameras, often before any count is available.</p>",
    ("Signals", "manage", "Patterns tell you the state of the crowd.", [("Lanes: coping", "Flow is organised."), ("Stop-and-go: near capacity", "Reduce inflow."), ("Turbulence: danger", "Act at once.")])),
 ],
 callouts=[C(0, "try", "Look for it", "<p>Next time you walk through a busy station or market, watch for lanes. Count how many there are across the corridor.</p>"),
           C(2, "model", "Like traffic", "<p>Stop-and-go waves in crowds behave much like phantom jams on motorways: no accident needed, just density near capacity.</p>")],
 explorer=dict(widget="lanes", intro="Blue walks right, orange walks left. Press Run, then change randomness and the number of people.", predict="Will raising randomness make lanes clearer or break them up?"),
 code=[dict(title="Counting lanes from a snapshot", lang="python", runnable=True, source="import random\nrandom.seed(1)\n# y position (m) and direction (+1 right, -1 left) of 60 walkers in an 8 m wide corridor\npeople = [(random.uniform(0, 8), random.choice([1, -1])) for _ in range(60)]\npeople.sort()\nbins = [0] * 16\nfor y, d in people:\n    bins[int(y / 0.5)] += d\nsigns = [1 if b > 0 else -1 for b in bins if b != 0]\nlanes = 1 + sum(1 for a, b in zip(signs, signs[1:]) if a != b)\nprint('net direction per 0.5 m strip:', bins)\nprint('lanes:', lanes)",
   explain="Splits the corridor into strips and counts how often the dominant direction changes. With random positions there are many short 'lanes'; organised crowds show few wide ones.", expected="lanes: (a number between 5 and 10 for random positions)")],
 takeaways=["Crowds self-organise: lanes, turn-taking and waves emerge from local rules.", "Lanes in counterflow reduce conflicts and raise flow.", "Stop-and-go waves travel backwards and signal density near capacity.", "Patterns are signals for crowd managers."],
 quiz=[Q("Why do lanes form in two-way corridors?", ["Signs tell people to", "Following someone going your way means fewer collisions", "People walk faster in lanes", "Lighting"], 1, "A small local advantage spreads into lanes."),
       Q("Stop-and-go waves travel…", ["Forwards, with the crowd", "Backwards through the crowd", "Sideways only", "Not at all"], 1, "Like traffic jams, they move upstream."),
       Q("Oscillating flow at a narrow two-way door can be removed by…", ["Painting arrows only", "Separate doors for each direction", "Faster walking", "More lighting"], 1, "Separating directions removes the conflict."),
       Q("Which pattern is the most urgent warning?", ["Lanes", "Zipper effect", "Irregular surges in a very dense crowd", "People chatting in groups"], 2, "Turbulent motion signals extreme density.")],
 glossary=[G("Self-organisation", "Large-scale patterns that arise from local interactions without central control."), G("Lane formation", "Sorting of a two-way flow into lanes of uniform direction."), G("Oscillation", "Alternating passage of opposite flows through a narrow opening."), G("Stop-and-go wave", "A wave of stopping that travels backwards through a dense crowd.")],
 resources=[RS("Helbing and Molnár (1995): Social force model", "https://doi.org/10.1103/PhysRevE.51.4282", "The model that reproduced lanes and oscillations."),
            RS("Helbing, Johansson and Al-Abideen (2007)", "https://arxiv.org/abs/physics/0701203", "Stop-and-go waves and turbulence at the Jamarat Bridge."),
            RS("Moussaïd, Helbing and Theraulaz (2011): How simple rules determine pedestrian behavior and crowd disasters", "https://doi.org/10.1073/pnas.1016507108", "Simple heuristics that produce lanes and turbulence.")],
 palace=("Living room", "Two armies of toy soldiers march across your living-room carpet in opposite directions. Without a word they fall into neat stripes, until the room fills and ripples of stopping roll backwards like a wave in a stadium."),
 qb=[("Recall", "Name three self-organised crowd patterns.", "Lane formation in counterflow, oscillations at narrow two-way doors, and stop-and-go waves at high density.", "All arise from local rules without a leader.", "Stripes, a swinging door, and a ripple."),
     ("Explain", "How do lanes form without anyone planning them?", "Walking behind someone going your way means fewer collisions; each person makes this small choice and the advantage spreads into lanes.", "Local advantage, repeated by many, becomes a global pattern.", "Ants following each other's trails."),
     ("Explain", "Why are stop-and-go waves a warning sign?", "They appear when density is near or above capacity, where small slowdowns grow; they can precede crowd turbulence, as at Jamarat in 2006.", "Instability means the system has no slack.", "A slinky about to tangle."),
     ("Apply", "How would you remove oscillations at a narrow door used in both directions?", "Make it one-way, for example separate entry and exit doors, or a central divider.", "Separate the conflicting flows.", "Two doors: one marked IN, one marked OUT."),
     ("Recall", "In which direction do stop-and-go waves travel?", "Backwards, against the walking direction.", "Each person reacts to the one in front after a short delay.", "Dominoes falling towards the back of the line."),
     ("Apply", "A control room sees lanes turn into stop-and-go motion. What should happen?", "Treat it as a sign of density near capacity: reduce or stop inflow, open relief routes and inform the crowd before turbulence develops.", "Act on the pattern before the count.", "A kettle starting to whistle: turn down the heat.")]))
# ------------------------------------------------------------------ 1.6
M.append(dict(id="1.6", go=1, slug="people-not-particles", title="People, not particles: behaviour and choice", minutes=35, tag="Behaviour", systems=["people", "manage"],
 summary="People choose routes, walk in groups, follow familiar paths and respond to information. Crowd behaviour is social, and 'panic' is rare. Good management works with that behaviour.",
 outcomes=["explain why people often use familiar routes even when others are free", "describe how groups and social identity shape crowd behaviour", "explain why information, not just space, changes how crowds move", "challenge the myth of mass panic with evidence"],
 narration_en="Physics explains a lot about crowds, but people are not particles. They have goals, habits and friends. When people leave a building, many head for the door they came in by, even when another exit is closer and empty. Families and friends walk together, and a group moves at the pace of its slowest member. People look at what others do and follow them. In emergencies, research shows that people mostly stay calm and help each other, partly because they come to feel part of a shared group. Real problems come from missing or confusing information, delays in deciding to move, and designs that send everyone the same way. That is why good crowd management is not only about widths and capacities. It is about signs that people understand, announcements they trust, stewards they can ask, and routes that match what people naturally do. In this module you will explore how behaviour changes evacuation times, and why the myth of mass panic is so persistent and so misleading.",
 narration_ar="تفسّر الفيزياء كثيراً عن الحشود، لكن الناس ليسوا جسيمات. لديهم أهداف وعادات وأصدقاء. فعندما يغادر الناس مبنى، يتجه كثير منهم إلى الباب الذي دخلوا منه، حتى لو كان مخرج آخر أقرب وفارغاً. وتسير العائلات والأصدقاء معاً، وتتحرك المجموعة بسرعة أبطأ أفرادها. وينظر الناس إلى ما يفعله الآخرون فيتبعونهم. وفي حالات الطوارئ، تُظهر الأبحاث أن الناس يبقون في الغالب هادئين ويساعد بعضهم بعضاً، ويعود ذلك جزئياً إلى شعورهم بالانتماء إلى مجموعة مشتركة. أما المشكلات الحقيقية فتأتي من المعلومات الناقصة أو المربكة، والتأخر في قرار التحرك، والتصاميم التي ترسل الجميع في الاتجاه نفسه. لهذا فإن الإدارة الجيدة للحشود لا تقتصر على العروض والسعات. بل تشمل لافتات يفهمها الناس، وإعلانات يثقون بها، ومنظّمين يمكن سؤالهم، وطرقاً تتوافق مع ما يفعله الناس بطبيعتهم. ستستكشف في هذه الوحدة كيف يغيّر السلوك أزمنة الإخلاء، ولماذا تستمر أسطورة الذعر الجماعي وكم هي مضللة.",
 diagram=dict(title="What shapes how people move", caption="Goals, habits, groups and information shape choices; those choices shape the flow.",
   nodes=[N("goal", "Goals", "where and how fast", 130, 100, "people", "Destination, urgency and desired speed differ: commuters hurry, families stroll, pilgrims follow a ritual sequence."),
          N("hab", "Habits and familiarity", "known routes first", 130, 260, "people", "People prefer routes and exits they know, often the one they arrived by (affiliation; Sime 1985)."),
          N("grp", "Groups", "move together", 130, 420, "people", "Most people at events are in groups. Groups walk at the pace of the slowest member and do not split easily."),
          N("info", "Information", "signs, announcements, stewards", 470, 100, "manage", "Clear, early, trusted information shortens decision times and spreads people across routes."),
          N("ch", "Choices", "route, exit, timing", 470, 260, "flow", "Decisions about which way, which exit and when to move. Their sum is the crowd's distribution across routes."),
          N("id", "Shared identity", "helping, not panic", 470, 420, "people", "In emergencies people often develop a shared identity and help each other (Drury, Cocking and Reicher 2009)."),
          N("flow", "Crowd outcome", "queues, times, risk", 780, 260, "risk", "Uneven use of exits, long pre-movement times and counterflows lengthen evacuations and create hot spots.")],
   edges=[E("goal", "ch"), E("hab", "ch", "bias"), E("grp", "ch", "slows, sticks"), E("info", "ch", "steers", "manage"), E("id", "ch", "cooperation"), E("ch", "flow", "adds up to")],
   tour=[T(["goal", "hab", "grp"], "People bring goals, habits and companions with them."),
         T(["ch"], "These shape their choices: which route, which exit, when to move.", [["goal", "ch"], ["hab", "ch"], ["grp", "ch"]]),
         T(["info"], "Information steers those choices, if it is clear, early and trusted.", [["info", "ch"]]),
         T(["id"], "In emergencies, shared identity usually makes people cooperate rather than panic.", [["id", "ch"]]),
         T(["flow"], "Add the choices up and you get the crowd's outcome: queues, times and risk.", [["ch", "flow"]])]),
 sections=[
  S("Familiar routes", "<p>Studies of evacuations and exit choice show that many people head for the exit they know, often the one they entered by, even if another is nearer and free. Sime (1985) called this <b>affiliation</b> with familiar places and people. The result: one exit queues while another stands empty.</p><div class=\"eq\">evacuation time ≈ time of the slowest exit to empty</div>",
    ("Familiar exits", "people", "People leave the way they came.", [("Affiliation", "Sime 1985."), ("Uneven exits", "One queues, one is empty."), ("Slowest exit decides", "Total time.")])),
  S("Groups", "<p>At events, most people come with family or friends. Groups move together, walk more slowly, and form walking shapes such as a line abreast or a V (Moussaïd et al. 2010). In evacuations, people look for their group before leaving, which adds to <b>pre-movement time</b>.</p>",
    ("Groups", "people", "Most people come with others.", [("Pace of the slowest", "Groups walk slower."), ("V and line shapes", "Moussaïd et al. 2010."), ("Gather first", "Longer pre-movement.")])),
  S("The myth of panic", "<p>Films and headlines show crowds 'panicking'. Research on real emergencies finds the opposite: people are mostly orderly and helpful, and selfish behaviour is rare (Drury, Cocking and Reicher 2009). What looks like panic in a crush is people being pushed by forces they cannot resist. Blaming panic draws attention away from design, information and management.</p>",
    ("No mass panic", "risk", "Cooperation is the norm.", [("Shared identity", "People help strangers."), ("Forces, not fear", "Crushes are physical."), ("Look at causes", "Design, information, management.")])),
  S("Information changes movement", "<p>People decide using what they see and hear. Clear signs in the crowd's languages, announcements from trusted voices, and visible stewards shorten decision times and balance routes. Poor information, or none, is a cause in many incidents: crowds keep pushing forward because those at the back cannot see what is happening at the front.</p>",
    ("Information", "manage", "Tell people what they need, early.", [("Languages and symbols", "Signs people understand."), ("Trusted voices", "Stewards, announcements."), ("Back can't see front", "Pushing without knowing.")])),
 ],
 callouts=[C(0, "try", "Explore it", "<p>Use the explorer: with 80% of people heading for the main entrance, how much longer does the evacuation take than with an even split?</p>"),
           C(3, "research", "Pilgrims and information", "<p>At the Hajj, pilgrims come from over 150 countries and speak many languages. Group leaders, colour-coded signs and staggered schedules are part of how information reaches them.</p>")],
 explorer=dict(widget="familiar", intro="1,200 people leave through two equal exits. Change the share heading for the entrance they came in by.", predict="If 90% use the main entrance, roughly how much longer does it take than an even split: 10%, 50% or 80%?"),
 code=[dict(title="Familiar exit bias", lang="python", runnable=True, source="N, cap = 1200, 3.0          # people, and people per second per exit\nfor share in [0.5, 0.6, 0.7, 0.8, 0.9]:\n    a, b = N * share, N * (1 - share)\n    t = max(a / cap + 20, b / cap + 25)   # walking time 20 s and 25 s\n    print(f'{share:.0%} at the main entrance: everyone out in {t/60:.1f} min')",
   explain="Total time is set by the slower exit. Try changing the walking times.", expected="50% at the main entrance: everyone out in 3.8 min\n...\n90% at the main entrance: everyone out in 6.3 min")],
 takeaways=["People often choose familiar routes, which leaves some exits underused.", "Groups move together and slow evacuations.", "Mass panic is a myth; cooperation is the norm, and crushes are physical.", "Clear, early, trusted information changes how crowds move."],
 quiz=[Q("Why do many people use the entrance they came in by during an evacuation?", ["It is always closest", "Familiarity and affiliation", "Signs require it", "It is the widest"], 1, "People prefer known routes (Sime 1985)."),
       Q("What does research say about behaviour in emergencies?", ["Mass panic is common", "People mostly cooperate and help", "People freeze", "Everyone runs"], 1, "Drury and colleagues found cooperation is the norm."),
       Q("How do groups affect evacuations?", ["They speed them up", "They slow them, as people gather and walk together", "No effect", "They always use the nearest exit"], 1, "Gathering adds to pre-movement time."),
       Q("Why do people at the back of a crowd keep pushing forward?", ["They want to hurt others", "They cannot see what is happening at the front", "They are told to", "To keep warm"], 1, "Missing information is a common cause.")],
 glossary=[G("Affiliation", "The tendency to move towards familiar people and places (Sime 1985)."), G("Pre-movement time", "Time between an alarm and the start of purposeful movement."), G("Social identity", "A sense of belonging to a group, which can grow among strangers in an emergency."), G("Mass panic", "The myth that crowds in danger turn irrational and selfish.")],
 resources=[RS("Drury, Cocking and Reicher (2009)", "https://doi.org/10.1348/014466608X357893", "Shared identity and cooperation in emergencies."),
            RS("Moussaïd et al. (2010): The walking behaviour of pedestrian social groups", "https://doi.org/10.1371/journal.pone.0010047", "Group walking shapes and speeds."),
            RS("Sieben, Schumann and Seyfried (2017): Collective phenomena in crowds", "https://doi.org/10.1371/journal.pone.0177328", "Why pedestrian dynamics needs social psychology.")],
 palace=("Study", "In your study, a crowd of tiny people ignores a glowing open door and squeezes back through the mouse hole they came in by, holding hands in chains of three, while a helpful stranger points at the empty door."),
 qb=[("Recall", "What is affiliation in exit choice?", "The tendency to move towards familiar places and people, so people often leave by the route they entered.", "Known routes feel safe.", "Homing pigeons returning through the same window."),
     ("Explain", "Why is 'mass panic' a poor explanation of crowd disasters?", "Evidence shows people mostly cooperate; crush deaths come from physical density and pressure caused by design, information and management failures.", "Blaming behaviour hides fixable causes.", "Blaming water for a flooded basement while the tap runs."),
     ("Calculate", "1,200 people, two exits of 3 per s each, 80% use one. Roughly when is the busy exit empty?", "960 ÷ 3 = 320 s plus about 20 s walking ≈ 5.7 minutes.", "The busy exit sets the total time.", "960 people through one door, three at a time."),
     ("Recall", "Name two ways groups change crowd movement.", "Groups walk at the pace of their slowest member, form shapes such as lines or Vs, and gather before evacuating, adding pre-movement time.", "Social bonds are part of the physics.", "A family as a slow, wide raft."),
     ("Apply", "How could you improve information for a multilingual crowd?", "Use pictograms and colour codes, signs in the main languages, group leaders who brief their groups, and visible stewards.", "Information must be understood to work.", "A traffic light needs no translation."),
     ("Explain", "Why do people at the back push forward even when the front is crushed?", "They cannot see or hear what is happening at the front, so they keep moving towards their goal.", "Information does not travel back through a dense crowd.", "A long queue where only the front sees the closed door.")]))
# ------------------------------------------------------------------ 1.7
M.append(dict(id="1.7", go=1, slug="when-crowds-become-dangerous", title="When crowds become dangerous", minutes=40, tag="Risk", systems=["risk", "people"],
 summary="Risk rises steeply with density. Above about 5 to 6 people per m² people lose control of their movement; forces add up through bodies, and crowd turbulence and collapse can follow.",
 outcomes=["describe how risk changes with density", "explain crowd pressure and crowd turbulence", "describe the causal chain of a crowd crush", "use the lessons of Hillsborough, Love Parade, Mina and Itaewon"],
 narration_en="Most crowds are safe. Danger comes when density gets very high. Above about five or six people per square metre, nobody can move independently: you are carried by the crowd. Forces from many people pushing, even gently, add up through bodies and can reach levels that make breathing impossible. Researchers Dirk Helbing, Anders Johansson and Habib Zein Al-Abideen studied video of the 2006 Jamarat Bridge disaster during the Hajj. They saw the crowd change from smooth flow to stop-and-go waves, and then to crowd turbulence: irregular, random-looking surges that pushed people several metres and made them fall. They measured crowd pressure, density times the variance of local speeds, and found it rose sharply before people fell. Once one person falls in such a crowd, others fall over them, and a crowd collapse spreads. The lesson from Hillsborough, Love Parade, Mina and Itaewon is the same: keep density well below critical levels, watch for warning signs, and never let large flows meet in narrow spaces.",
 narration_ar="معظم الحشود آمنة. يأتي الخطر عندما تصبح الكثافة عالية جداً. فوق نحو خمسة أو ستة أشخاص في المتر المربع لا يستطيع أحد أن يتحرك مستقلاً: فالحشد يحملك. والقوى الناتجة عن دفع كثير من الناس، ولو برفق، تتراكم عبر الأجساد وقد تبلغ حداً يجعل التنفس مستحيلاً. وقد درس الباحثون ديرك هيلبنغ وأندرس يوهانسون وحبيب زين العابدين تسجيلات كارثة جسر الجمرات عام ألفين وستة أثناء الحج. فرأوا الحشد يتحول من تدفق سلس إلى موجات توقف وانطلاق، ثم إلى اضطراب الحشد: اندفاعات غير منتظمة تبدو عشوائية تدفع الناس عدة أمتار وتُسقطهم. وقاسوا ضغط الحشد، أي الكثافة مضروبة في تباين السرعات المحلية، فوجدوا أنه يرتفع بحدة قبل سقوط الناس. وما إن يسقط شخص في مثل هذا الحشد حتى يسقط آخرون فوقه، فينتشر انهيار الحشد. والدرس من هيلزبره وموكب الحب ومنى وإيتايوون واحد: أبقِ الكثافة أدنى بكثير من المستويات الحرجة، وراقب علامات الإنذار، ولا تدع تدفقات كبيرة تلتقي في أماكن ضيقة.",
 diagram=dict(title="The chain to a crowd crush", caption="High density removes control; forces add up; turbulence and falls follow. Each link is a chance to intervene.",
   nodes=[N("dem", "Demand above capacity", "too many, too fast", 120, 100, "people", "More people arrive than routes and spaces can handle, often because flows meet or an exit is blocked."),
          N("den", "High density", "above about 5–6 per m²", 400, 100, "risk", "People touch on all sides and cannot move independently. Space per person is under about 0.2 m²."),
          N("force", "Forces add up", "through bodies", 680, 100, "risk", "Pushing from many people adds up along chains of bodies. Barriers and walls concentrate it. Breathing becomes difficult."),
          N("turb", "Crowd turbulence", "random-looking surges", 680, 280, "risk", "Irregular motion in all directions, people displaced several metres (Helbing et al. 2007). Crowd pressure ρ·Var(V) is high."),
          N("fall", "Falls and collapse", "progressive", 680, 440, "risk", "When people fall, others are pushed over them; a crowd collapse spreads. Victims die mostly of compressive asphyxia."),
          N("warn", "Warning signs", "stop-and-go, surges, calls", 400, 300, "data", "Stop-and-go waves, swaying surges, people climbing out, distress calls. At Itaewon, emergency calls started hours before the crush."),
          N("act", "Intervene early", "stop inflow, relieve, inform", 120, 300, "manage", "Stop or meter inflow, open relief routes, separate flows, inform those at the back. The earlier, the easier.")],
   edges=[E("dem", "den", "accumulates"), E("den", "force", "contact"), E("force", "turb"), E("turb", "fall"), E("den", "warn", "shows as"), E("warn", "act", "triggers", "manage"), E("act", "dem", "reduces", "manage")],
   tour=[T(["dem", "den"], "It starts when more people arrive than the space can pass, and density climbs.", [["dem", "den"]]),
         T(["force"], "Above about 5 to 6 per m², people lose control of their movement and forces add up through bodies.", [["den", "force"]]),
         T(["turb", "fall"], "Then crowd turbulence: surges that push people over. Falls spread into a collapse.", [["force", "turb"], ["turb", "fall"]]),
         T(["warn"], "There are warning signs along the way: stop-and-go waves, surges, distress calls.", [["den", "warn"]]),
         T(["act"], "Each sign is a chance to act: stop inflow, open relief routes, inform the crowd.", [["warn", "act"], ["act", "dem"]])]),
 sections=[
  S("Risk rises steeply with density", "<p>Below about 2 people per m² risk is low. Around <b>4 to 5 per m²</b> people are in frequent contact. Above about <b>5 to 6 per m²</b> they cannot move independently, and forces from others can be transmitted through them (Fruin 1993; Still 2014). Densities of 7 to 9 per m² or more have been measured in fatal incidents.</p>",
    ("Density and risk", "risk", "Risk is low, then rises steeply.", [("Under 2 per m²", "Low risk."), ("4–5 per m²", "Frequent contact."), ("Over 5–6 per m²", "Loss of control.")])),
  S("Crowd pressure and turbulence", "<p>Helbing, Johansson and Al-Abideen (2007) analysed video of the Jamarat Bridge entrance before the January 2006 disaster. Flow changed from laminar to <b>stop-and-go</b>, then to <b>crowd turbulence</b>. They defined crowd pressure as:</p><div class=\"eq\">P = ρ × Var(V) &nbsp;&nbsp;(density × variance of local velocity)</div><p>In their data, falls and deaths followed when P rose above about 0.02 per s². Pressure is high only when the crowd is both dense and moving irregularly, which makes it a useful warning signal.</p>",
    ("Crowd pressure", "data", "Dense and irregular means danger.", [("P = ρ × Var(V)", "Helbing et al. 2007."), ("About 0.02 per s²", "Jamarat data, one site."), ("Turbulence", "Surges in all directions.")])),
  S("Four disasters, one lesson", "<p><b>Hillsborough, Sheffield (1989)</b>: 97 deaths after a crowd was let into already full central pens. <b>Love Parade, Duisburg (2010)</b>: 21 deaths on a ramp that was the only way in and out. <b>Mina, during the Hajj (2015)</b>: two large flows met at a junction of streets 204 and 223; the official Saudi toll was 769, independent counts exceed 2,000. <b>Itaewon, Seoul (2022)</b>: 159 deaths in a sloping alley about 3 to 4 m wide, fed from both ends with no event plan.</p><p>In each case, flows were allowed to meet or accumulate in a confined space faster than it could empty.</p>",
    ("Four disasters", "risk", "Flows meeting in confined spaces.", [("Hillsborough 1989", "97 deaths, overfilled pens."), ("Love Parade 2010", "21 deaths, one ramp."), ("Mina 2015 and Itaewon 2022", "Meeting flows, narrow streets.")])),
  S("Intervene early", "<p>The chain has many links, and the early ones are easiest to break. <b>Before the event</b>: design routes so flows do not meet head-on, size spaces for the peak, plan for the unexpected. <b>During the event</b>: watch density and warning signs, stop or meter inflow early, open relief routes, and tell people at the back what is happening.</p>",
    ("Break the chain", "manage", "Earlier is easier.", [("Design", "No head-on flows in narrow spaces."), ("Monitor", "Density and warning signs."), ("Act", "Stop inflow, relieve, inform.")])),
 ],
 callouts=[C(1, "trap", "One number is not a law", "<p>The 0.02 s⁻² value comes from one site and one camera set-up. It is a research finding, not a design standard.</p>"),
           C(2, "research", "Go 3 returns here", "<p>Module 3.2 analyses these disasters in depth with the DIM-ICE model and the published evidence.</p>")],
 explorer=dict(widget="danger", intro="Raise density and the spread of local speeds, and watch crowd pressure.", predict="Can a crowd at 7 per m² have low crowd pressure?"),
 code=[dict(title="Crowd pressure from local speeds", lang="python", runnable=True, source="import statistics as st\n# local speeds (m/s) measured in one 1 m2 cell over 20 frames\ncalm      = [0.31, 0.30, 0.32, 0.29, 0.31, 0.30, 0.32, 0.31, 0.30, 0.29, 0.31, 0.30, 0.31, 0.32, 0.30, 0.31, 0.29, 0.30, 0.31, 0.30]\nturbulent = [0.05, 0.40, 0.10, 0.35, 0.02, 0.30, 0.15, 0.45, 0.00, 0.38, 0.08, 0.33, 0.12, 0.42, 0.03, 0.36, 0.11, 0.29, 0.06, 0.41]\nrho = 7.0   # people per m2\nfor name, v in [('calm', calm), ('turbulent', turbulent)]:\n    p = rho * st.pvariance(v)\n    print(f'{name:9s}: variance {st.pvariance(v):.4f}, pressure {p:.3f} per s2', '-> WARNING' if p > 0.02 else '')",
   explain="Same density, very different pressure. Speed variance is what turns a dense crowd into a dangerous one.", expected="calm     : variance 0.0001, pressure 0.001 per s2\nturbulent: variance 0.0244, pressure 0.171 per s2 -> WARNING")],
 takeaways=["Above about 5–6 per m² people lose control of their movement.", "Crowd pressure = density × variance of local velocity; high values preceded falls at Jamarat in 2006.", "Crushes follow a chain: demand above capacity, high density, forces, turbulence, falls.", "The disasters at Hillsborough, Love Parade, Mina and Itaewon share one cause: flows meeting or accumulating in confined spaces."],
 quiz=[Q("Above roughly what density can people no longer move independently?", ["1 per m²", "2 per m²", "5–6 per m²", "20 per m²"], 2, "Above about 5 to 6 per m² control is lost."),
       Q("Crowd pressure as defined by Helbing and colleagues is…", ["Density × variance of local velocity", "Flow × width", "Speed squared", "Number of people"], 0, "P = ρ × Var(V)."),
       Q("What do most crush victims die of?", ["Trampling", "Compressive asphyxia", "Heat stroke", "Heart attacks only"], 1, "They cannot breathe."),
       Q("A common factor in Mina 2015 and Itaewon 2022 was…", ["Fire", "Large flows meeting in narrow streets", "Bad weather", "Too many stewards"], 1, "Meeting flows in confined spaces.")],
 glossary=[G("Crowd pressure", "Local density × variance of local velocity; a warning indicator (Helbing et al. 2007)."), G("Crowd turbulence", "Irregular, random-looking motion of a very dense crowd that displaces people and causes falls."), G("Crowd collapse", "Progressive falling of people in a dense crowd."), G("Crowd crush", "An incident in which people are compressed so much that they are injured or killed.")],
 resources=[RS("Helbing, Johansson and Al-Abideen (2007): The dynamics of crowd disasters", "https://doi.org/10.1103/PhysRevE.75.046109", "Crowd pressure and turbulence at the Jamarat Bridge."),
            RS("Helbing and Mukerji (2012): Crowd disasters as systemic failures (Love Parade)", "https://doi.org/10.1140/epjds7", "A detailed open-access analysis of the Love Parade disaster."),
            RS("Hillsborough Independent Panel report (2012)", "https://www.gov.uk/government/publications/the-report-of-the-hillsborough-independent-panel", "The official review of the 1989 disaster.")],
 palace=("Stairwell", "On your stairs, a thick crowd of people stands still, then sways like a field of wheat in a gale; a pressure gauge on the banister swings past the red line marked 0.02."),
 qb=[("Recall", "At what density do people lose the ability to move independently?", "Above about 5 to 6 people per m².", "Below that, people can still choose small movements.", "Six people on one bath mat."),
     ("Recall", "Define crowd pressure.", "Local density multiplied by the variance of local velocity, P = ρ × Var(V) (Helbing et al. 2007).", "Dense and irregular means danger; dense and orderly is less dangerous.", "A pressure cooker needs both heat (density) and boiling (irregular motion)."),
     ("Explain", "Describe the chain of events leading to a crowd crush.", "Demand exceeds capacity, density rises, people lose control and forces add up through bodies, turbulence pushes people over, falls spread into a crowd collapse, and people die of compressive asphyxia.", "Each link is a place to intervene.", "A row of dominoes: remove an early one."),
     ("Recall", "What happened at the Love Parade in 2010?", "In Duisburg, 21 people died at a ramp that was the only way in and out of the festival area, where incoming and outgoing flows met.", "One route for both directions.", "A single door used by people going in and out at once."),
     ("Apply", "Name three warning signs control-room staff can watch for.", "Stop-and-go waves, swaying surges or turbulence, people climbing out over barriers, and distress or emergency calls.", "Patterns and behaviour show danger before counts.", "Smoke before fire."),
     ("Explain", "Why is the 0.02 per s² pressure value not a design standard?", "It comes from one site's video data and measurement method; values depend on how density and velocity are measured, so it is a research indicator, not a universal limit.", "Numbers travel badly between sites and methods.", "A single thermometer reading in one room.")]))
