M.append(dict(id="1.8", go=1, slug="planning-safe-crowds", title="Planning and managing safe crowds", minutes=40, tag="Practice", systems=["manage", "space"],
 summary="Safe events are designed, informed and managed in every phase. DIM-ICE and RAMP structure the risk analysis; flow rates and egress times size the exits.",
 outcomes=["use DIM-ICE to structure a crowd risk assessment", "describe RAMP analysis: routes, areas, movement and profile", "size an exit with a flow rate and an egress time", "list practical measures that keep density down"],
 narration_en="How do organisers keep crowds safe? Crowd scientist Keith Still teaches two tools. The first, DIM-ICE, crosses three things organisers control, design, information and management, with the three phases of an event, ingress, circulation and egress. Each of the nine cells is a question: is the design of the entry route adequate, does information reach people during circulation, how is egress managed? The second tool, RAMP, looks at routes, areas, movement over time, and the profile of the crowd. Then come numbers. Guidance for sports grounds in the United Kingdom, the Green Guide, gives planning flow rates of eighty two people per metre width per minute on level routes and sixty six on stepped routes, and egress times of up to eight minutes. Divide the number of people by the flow rate and the time, and you get the exit width needed. Finally, practical measures keep density down: separate flows, one-way systems, holding areas, staggered times, and stewards with clear authority to act.",
 narration_ar="كيف يحافظ المنظمون على سلامة الحشود؟ يدرّس عالم الحشود كيث ستيل أداتين. الأولى، DIM-ICE، تجمع بين ثلاثة أمور يتحكم فيها المنظمون، التصميم والمعلومات والإدارة، وبين المراحل الثلاث لأي فعالية، الدخول والتنقل والخروج. وكل خلية من الخلايا التسع سؤال: هل تصميم طريق الدخول كافٍ، وهل تصل المعلومات إلى الناس أثناء التنقل، وكيف يُدار الخروج؟ والأداة الثانية، RAMP، تنظر إلى الطرق والمناطق والحركة عبر الزمن وخصائص الحشد. ثم تأتي الأرقام. فالدليل الإرشادي لملاعب الرياضة في المملكة المتحدة، المعروف بالدليل الأخضر، يقدّم معدلات تدفق تخطيطية قدرها اثنان وثمانون شخصاً لكل متر من العرض في الدقيقة على الطرق المستوية، وستة وستون على الطرق المدرّجة، وأزمنة خروج تصل إلى ثماني دقائق. اقسم عدد الأشخاص على معدل التدفق والزمن، تحصل على عرض المخرج المطلوب. وأخيراً، تحافظ إجراءات عملية على انخفاض الكثافة: فصل التدفقات، وأنظمة الاتجاه الواحد، ومناطق الانتظار، والمواعيد المتدرجة، ومنظّمون لديهم صلاحية واضحة للتصرف.",
 diagram=dict(title="From risk analysis to exit widths", caption="DIM-ICE and RAMP find where risk lies; flow rates and times size the spaces; management measures keep density down on the day.",
   nodes=[N("dim", "DIM-ICE", "design · information · management", 140, 110, "manage", "Still's matrix: Design, Information, Management across Ingress, Circulation, Egress. Nine questions for every event (Still 2014)."),
          N("ramp", "RAMP", "routes · areas · movement · profile", 140, 290, "manage", "Routes people take, the areas they use, movement over time, and the profile of the crowd (age, culture, familiarity)."),
          N("rate", "Flow rates", "82 level, 66 stepped per m per min", 460, 110, "flow", "Green Guide (6th edition) planning rates for sports grounds, in people per metre width per minute."),
          N("time", "Target times", "egress up to 8 min", 460, 290, "risk", "The Green Guide sets egress times of up to 8 minutes, shorter where fire risk is higher."),
          N("width", "Exit width", "people ÷ (rate × time)", 780, 200, "space", "Example: 6,000 people, level route, 8 minutes: 6,000 ÷ (82 × 8) ≈ 9.1 m of exit width."),
          N("ops", "On the day", "stewards, metering, information", 460, 450, "manage", "One-way systems, holding areas, staggered times, metering at gates, clear communication, and stewards empowered to stop flows.")],
   edges=[E("dim", "ramp", "with"), E("dim", "rate", "design"), E("rate", "width", "÷"), E("time", "width", "÷"), E("ramp", "ops", "plans"), E("width", "ops", "limits", "manage")],
   tour=[T(["dim"], "Start with DIM-ICE: what can go wrong in design, information and management, in each phase?"),
         T(["ramp"], "Then RAMP: which routes, which areas, how movement changes over time, and who the crowd is.", [["dim", "ramp"]]),
         T(["rate", "time"], "Choose planning flow rates and target times from the guidance that applies.", [["dim", "rate"]]),
         T(["width"], "Width needed = people ÷ (rate × time).", [["rate", "width"], ["time", "width"]]),
         T(["ops"], "On the day, management keeps density down: stewards, metering, information.", [["ramp", "ops"], ["width", "ops"]])]),
 sections=[
  S("DIM-ICE", "<p>Keith Still's <b>DIM-ICE</b> model crosses what organisers control with the phases of an event:</p><table><thead><tr><th></th><th>Ingress</th><th>Circulation</th><th>Egress</th></tr></thead><tbody><tr><td><b>Design</b></td><td>entry routes, gates</td><td>concourses, toilets</td><td>exits, routes away</td></tr><tr><td><b>Information</b></td><td>tickets, signs</td><td>screens, announcements</td><td>exit signs, PA</td></tr><tr><td><b>Management</b></td><td>queues, searches</td><td>stewarding</td><td>staggered release</td></tr></tbody></table><p>Each cell is a question to ask. Clusters of weak cells point to where an incident is likely.</p>",
    ("DIM-ICE", "manage", "Nine questions for every event.", [("Design, Information, Management", "What you control."), ("Ingress, Circulation, Egress", "When it matters."), ("Weak clusters", "Where incidents start.")])),
  S("RAMP analysis", "<p><b>RAMP</b> asks about <b>Routes</b> (where people come from and go), <b>Areas</b> (holding and moving spaces, measured), <b>Movement</b> (arrival and departure profiles over time) and <b>Profile</b> (who the crowd is: age, culture, familiarity, purpose). A football crowd, a family festival and a pilgrimage need different plans even in the same space.</p>",
    ("RAMP", "manage", "Routes, Areas, Movement, Profile.", [("Routes", "Directions and modal split."), ("Areas", "Measured holding and moving spaces."), ("Movement and Profile", "Timing and who the crowd is.")])),
  S("Sizing exits with flow rates", "<p>The Green Guide (6th edition) gives planning flow rates of <b>82 people per metre width per minute</b> on level routes and <b>66</b> on stepped routes, and egress times of up to <b>8 minutes</b> (less where fire risk is higher).</p><div class=\"eq\">exit width = people ÷ (flow rate × egress time)</div><p>Example: 6,000 people, level route, 8 minutes: 6,000 ÷ (82 × 8) ≈ <b>9.1 m</b>. Stepped route: 6,000 ÷ (66 × 8) ≈ 11.4 m. Note these are per minute, unlike the per-second specific flows of module 1.4.</p>",
    ("Exit width", "space", "People ÷ (rate × time).", [("82 level, 66 stepped", "Per metre per minute."), ("Up to 8 minutes", "Egress time."), ("6,000 → 9.1 m", "Level, 8 minutes.")])),
  S("Keeping density down on the day", "<p>Good plans fail without good operations. Measures that work: <b>separate in and out flows</b>; <b>one-way systems</b>; <b>holding areas</b> and <b>metering</b> to release people in batches; <b>staggered</b> start and finish times; clear <b>information</b> in the crowd's languages; and <b>stewards</b> with the authority to stop inflow when density rises.</p>",
    ("On the day", "manage", "Operations keep plans safe.", [("Separate flows", "In and out apart."), ("Meter and stagger", "Release in batches."), ("Empowered stewards", "Stop inflow early.")])),
 ],
 callouts=[C(2, "trap", "Rates are not laws of nature", "<p>Planning rates include safety margins and apply to the venues they were written for. Use the guidance that applies where you work, and check routes beyond the exit too.</p>"),
           C(3, "try", "Plan it", "<p>A stand of 4,000 needs to leave in 8 minutes by a stepped route. Width? <i>4,000 ÷ (66 × 8) ≈ 7.6 m.</i></p>")],
 explorer=dict(widget="egress", intro="Size the exits for a section of a venue using Green Guide flow rates.", predict="If you halve the target egress time, how much more exit width do you need?"),
 code=[dict(title="Exit width calculator", lang="python", runnable=True, source="def exit_width(people, minutes, stepped=False):\n    rate = 66 if stepped else 82        # people per metre width per minute (Green Guide, 6th ed.)\n    return people / (rate * minutes)\n\nfor people in [2000, 6000, 12000]:\n    print(f'{people:6d} people: level {exit_width(people, 8):.1f} m, stepped {exit_width(people, 8, True):.1f} m (8 min)')",
   explain="Width = people ÷ (rate × time). Change the time to 6 minutes for a higher fire risk.", expected="  2000 people: level 3.0 m, stepped 3.8 m (8 min)\n  6000 people: level 9.1 m, stepped 11.4 m (8 min)")],
 takeaways=["DIM-ICE crosses Design, Information and Management with Ingress, Circulation and Egress.", "RAMP analysis looks at Routes, Areas, Movement and Profile.", "Exit width = people ÷ (flow rate × egress time); the Green Guide uses 82 (level) and 66 (stepped) per metre per minute and up to 8 minutes.", "On the day, separate flows, metering, information and empowered stewards keep density down."],
 quiz=[Q("In DIM-ICE, the 'I' in DIM stands for…", ["Ingress", "Information", "Injury", "Inspection"], 1, "Design, Information, Management; then Ingress, Circulation, Egress."),
       Q("6,000 people must leave in 8 minutes by a level route at 82 per m per min. Width?", ["4.6 m", "9.1 m", "18 m", "73 m"], 1, "6,000 ÷ (82 × 8) ≈ 9.1 m."),
       Q("RAMP stands for…", ["Routes, Areas, Movement, Profile", "Risk, Assessment, Management, Plan", "Ramps, Aisles, Main exits, Paths", "Rate, Area, Mass, Pressure"], 0, "Still's RAMP analysis."),
       Q("Why are stepped routes given a lower flow rate than level routes?", ["Stairs are wider", "People move more slowly and carefully on steps", "Fewer people use stairs", "To save money"], 1, "Steps slow people down.")],
 glossary=[G("DIM-ICE", "Still's risk model crossing Design, Information and Management with Ingress, Circulation and Egress."), G("RAMP analysis", "Routes, Areas, Movement and Profile: a structured look at a crowd and its site."), G("Egress time", "The time for people to leave a space or venue."), G("Green Guide", "Guide to Safety at Sports Grounds (UK), giving planning flow rates and egress times."), G("Metering", "Controlling the rate at which people enter a space.")],
 resources=[RS("Still et al. (2020): Place crowd safety, crowd science? (open access)", "https://e-space.mmu.ac.uk/625559/", "DIM-ICE applied to real case studies."),
            RS("Sports Grounds Safety Authority: the Green Guide", "https://sgsa.org.uk/greenguide/", "The Guide to Safety at Sports Grounds, 6th edition."),
            RS("HSE: Managing crowds safely (HSG154)", "https://www.hse.gov.uk/pubns/books/hsg154.htm", "Planning, stewarding and monitoring crowds.")],
 palace=("Garden gate", "At your garden gate a steward holds a board with nine squares (DIM × ICE) and a stopwatch reading 8:00; a tape measure unrolls 9.1 metres as 6,000 garden gnomes walk out in rows of 82."),
 qb=[("Recall", "What does DIM-ICE stand for?", "Design, Information, Management crossed with Ingress, Circulation, Egress.", "What you control, at each phase.", "A dim ice cube with nine frozen squares."),
     ("Recall", "What does RAMP stand for?", "Routes, Areas, Movement, Profile.", "Where, how much space, when, and who.", "A ramp with four steps: route, area, movement, profile."),
     ("Calculate", "4,000 people, stepped route, 8 minutes. Exit width?", "4,000 ÷ (66 × 8) ≈ 7.6 m.", "Width = people ÷ (rate × time).", "66 people per metre per minute on the stairs."),
     ("Explain", "Why does the same space need different plans for different crowds?", "Profiles differ: age, mobility, culture, familiarity, purpose and group size change speeds, routes and behaviour.", "RAMP's P matters as much as its A.", "A school trip and a marathon finish in the same park."),
     ("Apply", "Name four measures that keep density down on the day.", "Separating in and out flows, one-way systems, holding areas and metering, staggered times, clear multilingual information, and empowered stewards.", "Plans need operations.", "A traffic police officer with a stop sign."),
     ("Explain", "Why is egress often the hardest phase?", "Everyone wants to leave at once at the end, so the peak flow is concentrated in a short time, often with tired people and darkness.", "Arrivals spread out; departures do not.", "A cinema emptying when the credits roll.")]))
